"""Cuaderno del estudiante, 4.º básico Lenguaje y Comunicación, OA 22 (escucha literaria de obras completas) y OA 23 (comprensión de textos orales).

Todos los textos son originales de este cuaderno (no son obras con derechos ni tradiciones reales); en la
escucha, los textos del enunciado los lee en voz alta una persona adulta. Las obras reales (cuentos
folclóricos, poemas, mitos y leyendas, capítulos de novelas) las elige y lee el docente.
"""
from __future__ import annotations

from student_lessons import arith, ex, register

OA22, OA23 = "LE04 OA 22", "LE04 OA 23"
E = ex


def task(statement, example, criteria, evidence, errors, feedback):
    return {"statement": statement, "example": example, "criteria": criteria, "evidence": evidence, "errors": errors, "feedback": feedback}


def L(oa, n, materials, use, prior, explain, vocab, worked, mistakes, tiers, ctx, sc, open_task, reinforce, extend):
    register(
        oa, n, materials=materials, use=use, prior=prior, explain=explain, vocab=vocab,
        worked=[{"title": t, "problem": p, "steps": s, "answer": a} for t, p, s, a in worked],
        mistakes=[{"wrong": w, "why": y, "fix": f} for w, y, f in mistakes],
        tiers=dict(zip(("recovery", "understand", "apply", "reason", "challenge"), tiers)),
        context=ctx, selfcheck=sc, open_task=task(*open_task), reinforce=reinforce, extend=extend,
    )


TORTUGA = ("«La tortuga Mora quería llegar a la cima del cerro antes del invierno. Caminó un día entero, pero el viento soplaba en contra "
           "y la hacía retroceder. Entonces vio un caracol que se escondía tras una piedra grande. Mora hizo lo mismo y avanzó de roca en roca, "
           "protegida del viento. Cuando llegó a la cima, vio el valle cubierto de flores amarillas.»")
POEMA = "«La lluvia toca la ventana, / golpea suave, tiene prisa; / en cada gota hay una campana / que canta bajito, sin risa.»"
LAGO = ("«Cuentan que en un valle había un lago sin nombre. Una niña se asomó y vio su cara en el agua. «Eres un espejo», dijo. "
        "Desde entonces, la gente del valle lo llama Lago Espejo. Dicen que, si uno mira con calma, el lago devuelve la sonrisa de quien lo mira.»")

